  private s: number;

  private static assertState(state: number): void {
10→    if (!Number.isSafeInteger(state) || state < 0 || state > 0xffffffff) {
      throw new RangeError("RNG state must be an unsigned 32-bit integer");
    }
  }

  constructor(seed: number) {
    this.s = seed >>> 0;
  }

