arguments.new_string:
export function loadSavedGame(storage: Storage = localStorage): SavedGame | null {
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const saved: unknown = JSON.parse(raw);
    return validSavedGame(saved) ? saved : null;
  } catch {
    return null;
  }
}

/** Replace the single in-progress run. Caps the action log so a long shift stays loadable. */
export function saveSavedGame(saved: SavedGame, storage: Storage = localStorage): void {
  const record: SavedGame = {
    ...saved,
    schemaVersion: 1,
    actions: saved.actions.slice(0, MAX_ACTIONS),
  };
  if (!validSavedGame(record)) return;
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(record));
  } catch {
    // Persistence must never interrupt gameplay.
  }
}

/** Drop the in-progress run. Restart uses this so the next launch cannot replay the old seed. */
export function clearSavedGame(storage: Storage = localStorage): void {
  try {
    storage.removeItem(STORAGE_KEY);
  } catch {
    // Persistence must never interrupt gameplay.
  }
}

export const PREVIEW_RESIZE_MESSAGE = "gamepigeon:preview-resize";

/** Logical overlay frames. Keep in lockstep with the README window-size table. */
export const COMPACT_SIZE = { width: 600, height: 850 } as const;
export const EXPANDED_SIZE = { width: 830, height: 900 } as const;
export const PILL_SIZE = { width: 144, height: 48 } as const;
export const MIN_SIZE = { width: 500, height: 700 } as const;

export type OverlayFrame = "compact" | "expanded" | "pill";

export function overlayFrameSize(frame: OverlayFrame): { readonly width: number; readonly height: number } {
  if (frame === "expanded") return EXPANDED_SIZE;
  if (frame === "pill") return PILL_SIZE;
  return COMPACT_SIZE;
}

