/**
 * Agent-stop pause: the harness Stop hook holds a run until the player
 * continues, goes back to coding, or the next prompt resumes it.
 */

export interface AgentPauseState {
  /** The "Paused" dialog is on screen. */
  dialogOpen: boolean;
  /** Clock, ticks, and workers must not advance. */
  held: boolean;
}

export const RUNNING: AgentPauseState = { dialogOpen: false, held: false };

/** Stop hook: freeze the run and ask what to do next. */
export function pauseForAgent(): AgentPauseState {
  return { dialogOpen: true, held: true };
}

/** "Continue playing" — dismiss the dialog and let the shift run. */
export function continueFromPause(): AgentPauseState {
  return { dialogOpen: false, held: false };
}

/**
 * "Back to coding" — leave the dialog, keep the run frozen so a later
 * `gamepigeon:resume` is what starts the clock again.
 */
export function dismissPauseKeepHeld(): AgentPauseState {
  return { dialogOpen: false, held: true };
}

/** Host `--show` / `gamepigeon:resume`: overlay gone, clock free to run. */
export function resumeFromHost(): AgentPauseState {
  return { dialogOpen: false, held: false };
}

export function resetPause(): AgentPauseState {
  return RUNNING;
}

export function shouldHonorAgentPause(autoPauseOnStop: boolean, screen: string): boolean {
  return autoPauseOnStop && screen === "game";
}

