import { describe, expect, test } from "bun:test";
import { REGISTRY } from "../src/games/registry.js";
import {
  clearSavedGame,
  loadSavedGame,
  restoreGame,
  saveSavedGame,
  type SavedGame,
} from "./persistence.js";

function memoryStorage(initial: Record<string, string> = {}): Storage {
  const map = new Map(Object.entries(initial));
  return {
    get length() { return map.size; },
    clear() { map.clear(); },
    getItem(key) { return map.has(key) ? map.get(key)! : null; },
    setItem(key, value) { map.set(key, String(value)); },
    removeItem(key) { map.delete(key); },
    key(index) { return [...map.keys()][index] ?? null; },
  };
}

const KEY = "gamepigeon.arcade.active-game.v1";

function sample(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "usr_test",
    gameId: "restaurant-arena",
    gameVersion: "1",
    variationId: "dinner-rush",
    seed: 42,
    actions: ["sim_toggle", "tick"],
    ...overrides,
  };
}

describe("saved-game persistence", () => {
  test("round-trips a SavedGame under the documented storage key", () => {
    const storage = memoryStorage();
    const saved = sample();
    saveSavedGame(saved, storage);
    expect(storage.getItem(KEY)).toBeTruthy();
    expect(loadSavedGame(storage)).toEqual(saved);
  });

  test("clearing drops the record so the next launch cannot resume it", () => {
    const storage = memoryStorage();
    saveSavedGame(sample(), storage);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("rejects malformed or oversized records", () => {
    expect(loadSavedGame(memoryStorage({ [KEY]: "not-json" }))).toBeNull();
    expect(loadSavedGame(memoryStorage({ [KEY]: JSON.stringify({ schemaVersion: 2 }) }))).toBeNull();
    expect(loadSavedGame(memoryStorage({
      [KEY]: JSON.stringify(sample({ seed: 1.5 })),
    }))).toBeNull();
    expect(loadSavedGame(memoryStorage({
      [KEY]: JSON.stringify(sample({ actions: Array.from({ length: 50_001 }, () => "tick") })),
    }))).toBeNull();
  });

  test("caps the action log on write so a long shift stays loadable", () => {
    const storage = memoryStorage();
    saveSavedGame(sample({ actions: Array.from({ length: 50_001 }, () => "tick") }), storage);
    const loaded = loadSavedGame(storage);
    expect(loaded).not.toBeNull();
    expect(loaded!.actions).toHaveLength(50_000);
  });

  test("restore rebuilds the same run action-by-action", () => {
    const entry = REGISTRY.find((item) => item.id === "restaurant-arena")!;
    const saved = sample({ actions: ["sim_toggle"] });
    const restored = restoreGame(entry, saved);
    expect(restored).not.toBeNull();
    expect(restored!.actions).toEqual(["sim_toggle"]);
    expect(restored!.game.name).toBe("restaurant-arena");
  });

  test("restore refuses a different game version instead of replaying the old seed", () => {
    const entry = REGISTRY.find((item) => item.id === "restaurant-arena")!;
    expect(restoreGame(entry, sample({ gameVersion: "0" }))).toBeNull();
    expect(restoreGame(entry, sample({ gameId: "missing" }))).toBeNull();
  });
});

import { describe, expect, test } from "bun:test";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  PREVIEW_RESIZE_MESSAGE,
  isTauri,
  overlayFrameSize,
  overlayLogicalSize,
} from "./tauri-bridge.js";

describe("overlay window frames", () => {
  test("exports the README sizes", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("maps each frame name onto those sizes", () => {
    expect(overlayFrameSize("compact")).toEqual(COMPACT_SIZE);
    expect(overlayFrameSize("expanded")).toEqual(EXPANDED_SIZE);
    expect(overlayFrameSize("pill")).toEqual(PILL_SIZE);
  });

  test("preview resize events keep the same type the iframe listens for", () => {
    expect(PREVIEW_RESIZE_MESSAGE).toBe("gamepigeon:preview-resize");
  });

  test("logical sizes work without a Tauri runtime", () => {
    expect(isTauri()).toBe(false);
    const size = overlayLogicalSize(600, 850);
    expect(size.width).toBe(600);
    expect(size.height).toBe(850);
  });
});

import { describe, expect, test } from "bun:test";
import {
  RUNNING,
  continueFromPause,
  dismissPauseKeepHeld,
  pauseForAgent,
  resetPause,
  resumeFromHost,
  shouldHonorAgentPause,
} from "./pause-state.js";

describe("agent-stop pause", () => {
  test("Stop freezes the run and opens the paused dialog", () => {
    expect(pauseForAgent()).toEqual({ dialogOpen: true, held: true });
  });

  test("Continue playing dismisses the dialog and releases the clock", () => {
    expect(continueFromPause()).toEqual({ dialogOpen: false, held: false });
  });

  test("Back to coding leaves the run held after the dialog closes", () => {
    expect(dismissPauseKeepHeld()).toEqual({ dialogOpen: false, held: true });
  });

  test("a later host resume clears both the dialog and the hold", () => {
    expect(resumeFromHost()).toEqual(RUNNING);
    expect(resetPause()).toEqual(RUNNING);
  });

  test("honors auto-pause only while a run is on screen", () => {
    expect(shouldHonorAgentPause(true, "game")).toBe(true);
    expect(shouldHonorAgentPause(false, "game")).toBe(false);
    expect(shouldHonorAgentPause(true, "menu")).toBe(false);
  });
});

