function dialog(id: "return-prompt" | "how-to-play" | "signout-prompt"): HTMLElement | null {
  return document.querySelector<HTMLElement>(`#${id}`);
}

function setDialogOpen(id: "return-prompt" | "how-to-play" | "signout-prompt", open: boolean): void {
  const element = dialog(id);
  if (element) element.hidden = !open;
}

function showHowToPlay(): void {
  setDialogOpen("how-to-play", true);
}

function hideHowToPlay(): void {
  setDialogOpen("how-to-play", false);
}

function showSignOutPrompt(): void {
  if (!isSignedIn()) return;
  setDialogOpen("signout-prompt", true);
}

function hideSignOutPrompt(): void {
  setDialogOpen("signout-prompt", false);
}

function showPauseDialog(): void {
  setDialogOpen("return-prompt", true);
}

function hidePauseDialog(): void {
  setDialogOpen("return-prompt", false);
}

function updateResizeButton(): void {
  const button = document.querySelector<HTMLButtonElement>("#resize");
  if (!button) return;
  button.textContent = expanded ? "↙" : "↗";
  button.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

async function applyFrame(
  size: { width: number; height: number },
  min?: { width: number; height: number },
): Promise<void> {
  try {
    if (min) await windowHandle.setMinSize(overlayLogicalSize(min.width, min.height));
    await windowHandle.setSize(overlayLogicalSize(size.width, size.height));
  } catch {
    // Preview and older shells still get the CSS frame even if setSize throws.
  }
}

function playableFrameSize(): { width: number; height: number } {
  return expanded ? EXPANDED_SIZE : COMPACT_SIZE;
}

async function minimizeToPill(): Promise<void> {
  hidePauseDialog();
  hideHowToPlay();
  hideSignOutPrompt();
  minimizedToPill = true;
  document.body.dataset.mode = "pill";
  await applyFrame(PILL_SIZE);
}

async function restoreFromPill(): Promise<void> {
  if (!minimizedToPill && document.body.dataset.mode !== "pill") return;
  minimizedToPill = false;
  delete document.body.dataset.mode;
  expanded = false;
  updateResizeButton();
  await applyFrame(COMPACT_SIZE, MIN_SIZE);
}

async function toggleExpanded(): Promise<void> {
  if (minimizedToPill || document.body.dataset.mode === "pill") {
    await restoreFromPill();
    return;
  }
  expanded = !expanded;
  updateResizeButton();
  await applyFrame(playableFrameSize(), MIN_SIZE);
}

function variationIdFor(selected: GameEntry, index = variationCursor): string {
  return selected.variations[index]?.id ?? selected.variations[0]?.id ?? "classic";
}

function resolveVariation(selected: GameEntry, variationId?: string): string {
  if (variationId && selected.variations.some((variation) => variation.id === variationId)) return variationId;
  return selected.variations[0]?.id ?? "classic";
}

function randomSeed(avoid?: number): number {
  let seed = (Math.random() * 0x100000000) >>> 0;
  if (avoid !== undefined && seed === avoid) seed = (seed + 1) >>> 0;
  return seed;
}

function currentOwnerId(): string {
  return signedInUser()?.id ?? "";
}

function persistActiveGame(): void {
  if (!entry || !game || gameEnded) return;
  const record: SavedGame = {
    schemaVersion: 1,
    ownerId: currentOwnerId(),
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: variationIdFor(entry),
    seed: activeSeed,
    actions: [...actionLog],
  };
  savedGame = record;
  saveSavedGame(record);
}

function clearTicks(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

function stopRunChrome(): void {
  clearTicks();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
}

function syncScheduler(): void {
  clearTicks();
  if (!game || gameEnded || agentPause.held || game.isOver()) {
    workerOrchestrator?.pause();
    return;
  }
  const ms = game.tickMs?.() ?? 0;
  if (workerOrchestrator) {
    if (ms > 0) workerOrchestrator.start();
    else workerOrchestrator.pause();
    return;
  }
  if (ms <= 0) return;
  tickTimer = window.setTimeout(() => {
    tickTimer = undefined;
    if (!game || gameEnded || agentPause.held) return;
    if ((game.tickMs?.() ?? 0) <= 0) return;
    performAction("tick");
  }, ms);
}

function bindPauseState(next: AgentPauseState): void {
  agentPause = next;
  if (next.dialogOpen) showPauseDialog();
  else hidePauseDialog();
  syncScheduler();
}

function pauseRunForAgent(): void {
  if (!shouldHonorAgentPause(settings.autoPauseOnStop, screen)) return;
  workerOrchestrator?.pause();
  bindPauseState(pauseForAgent());
}

function continuePlaying(): void {
  bindPauseState(continueFromPause());
}

function backToCoding(): void {
  bindPauseState(dismissPauseKeepHeld());
  void windowHandle.hide();
}

function resumeRunFromHost(): void {
  bindPauseState(resumeFromHost());
  void restoreFromPill();
}

function abandonActiveTrace(reason: EpisodeEndReason): void {
  if (!activeTrace || !entry || !game) return;
  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: variationIdFor(entry),
    outcome: "abandoned",
    score: game.score(),
    success: game.hasWon(),
    duration_ms: Math.max(0, Date.now() - gameStartedAt),
    actions_taken: actionsTaken,
  }, sessionReceiptId);
  submitTrace(activeTrace, reason);
  activeTrace = undefined;
}

function leaveRunToMenu(): void {
  hideHowToPlay();
  hidePauseDialog();
  bindPauseState(resetPause());
  if (game && entry && !gameEnded) {
    persistActiveGame();
    abandonActiveTrace("user_quit");
  }
  stopRunChrome();
  game = undefined;
  entry = undefined;
  gameEnded = false;
  replaying = false;
  actionLog = [];
  screen = "menu";
  drawMenu();
}

function recordRunAction(action: string, actor: TraceActor): void {
  actionLog.push(action);
  persistActiveGame();
  if (!activeTrace) return;
  appendOverlayAction(activeTrace, action, actor);
  persistTrace(activeTrace);
  scheduleTraceFlush(activeTrace);
}

function showGameOverOverlay(): void {
  if (!game || !entry) return;
  if (screenElement.querySelector(".game-end-overlay")) return;
  const won = game.hasWon();
  const host = screenElement.querySelector(".board") ?? screenElement;
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = won ? "win" : "loss";
  const isArena = game.name === "restaurant-arena";
  overlay.innerHTML = `<div class="game-end-content${isArena ? " arena-end-content" : ""}">
    <h2 class="game-end-title">${won ? "Shift complete" : "Shift over"}</h2>
    ${sessionReceiptHtml()}
    ${getArenaDebriefHtml()}
    ${getArenaEvidenceHtml()}
    ${getArenaTimelineHtml()}
    <div class="game-end-actions">
      <button type="button" class="primary" data-restart>Play again</button>
      <button type="button" data-menu>Menu</button>
      ${isArena ? `<div class="export-trace-group">
        <button type="button" class="export-trace-btn" data-action="export-trace">Export Trace</button>
        <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl">JSONL</button>
      </div>` : ""}
    </div>
  </div>`;
  host.append(overlay);
}

function finishRun(reason: EpisodeEndReason): void {
  if (gameEnded || !game || !entry) return;
  gameEnded = true;
  stopWorkerOrchestrator();
  clearTicks();
  const completed = reason === "game_over" || reason === "won" || reason === "lost";
  const variation = variationIdFor(entry);
  lastReplay = {
    entry,
    variationId: variation,
    seed: activeSeed,
    actions: [...actionLog],
    arenaTrace: game.name === "restaurant-arena"
      ? captureArenaTrace(game as unknown as RestaurantGame, {
        runKind: "live",
        ...(sessionReceiptId ? { sessionId: sessionReceiptId } : {}),
      })
      : undefined,
  };
  if (activeTrace) {
    captureOverlayEvent("game.ended", {
      game_type: entry.id,
      variation_id: variation,
      outcome: completed ? "completed" : "abandoned",
      score: game.score(),
      success: game.hasWon(),
      duration_ms: Math.max(0, Date.now() - gameStartedAt),
      actions_taken: actionsTaken,
    }, sessionReceiptId);
    submitTrace(activeTrace, reason, completed ? game.score() : undefined);
    if (completed) {
      void invoke("append_local_score", {
        score: {
          game_id: activeTrace.gameId,
          game_type: entry.id,
          variation_id: variation,
          score: game.score(),
          success: game.hasWon(),
          completed_at: new Date().toISOString(),
          duration_ms: Math.max(0, Date.now() - gameStartedAt),
          platform: "overlay",
        },
      }).then(() => refreshLocalScores()).catch(() => undefined);
      clearSavedGame();
      savedGame = undefined;
    }
    activeTrace = undefined;
  }
  showGameOverOverlay();
}

function handleArenaUi(action: "menu" | "restart" | "help"): void {
  if (action === "menu") leaveRunToMenu();
  else if (action === "restart") restartRun();
  else showHowToPlay();
}

function startRun(selected: GameEntry, variationId: string, opts?: { seed?: number; actions?: string[] }): void {
  if (!selected.create) return;
  hideHowToPlay();
  hidePauseDialog();
  bindPauseState(resetPause());
  stopRunChrome();
  entry = selected;
  variationCursor = Math.max(0, selected.variations.findIndex((variation) => variation.id === variationId));
  if (variationCursor < 0) variationCursor = 0;
  const variation = variationIdFor(selected);
  activeSeed = opts?.seed ?? randomSeed();
  game = selected.create(variation);
  game.reset(activeSeed);
  actionLog = [];
  for (const action of opts?.actions ?? []) {
    if (!(game.actions as readonly string[]).includes(action)) continue;
    if (game.step(action).moved) actionLog.push(action);
  }
  gameStartedAt = Date.now();
  actionsTaken = actionLog.length;
  gameEnded = false;
  replaying = false;
  activeTrace = createOverlayTrace(selected, variation, activeSeed, gameStartedAt);
  sessionReceiptId = activeTrace.gameId;
  persistTrace(activeTrace);
  persistActiveGame();
  captureOverlayEvent("game.started", { game_type: selected.id, variation_id: variation });
  screen = "game";
  renderGameScreen();
  attachWorkerOrchestrator(game);
  syncScheduler();
  if (game.isOver()) finishRun("game_over");
}

function startSelectedVariation(): void {
  if (!entry || !isPlayable(entry)) return;
  startRun(entry, variationIdFor(entry), { seed: randomSeed() });
}

function resumeSaved(): void {
  if (!savedGame) return;
  const selected = findGame(savedGame.gameId);
  if (!selected || !isPlayable(selected)) return;
  const restored = restoreGame(selected, savedGame);
  if (!restored) {
    startRun(selected, savedGame.variationId, { seed: randomSeed(savedGame.seed) });
    return;
  }
  startRun(selected, savedGame.variationId, { seed: savedGame.seed, actions: restored.actions });
}

function restartRun(): void {
  if (!entry) return;
  const selected = entry;
  const variation = variationIdFor(selected);
  const previousSeed = activeSeed;
  if (game && !gameEnded && activeTrace) abandonActiveTrace("restart");
  stopRunChrome();
  clearSavedGame();
  savedGame = undefined;
  startRun(selected, variation, { seed: randomSeed(previousSeed) });
}

function launchById(gameId?: string | null, variationId?: string | null): boolean {
  if (!gameId) return false;
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return false;
  startRun(selected, resolveVariation(selected, variationId ?? undefined), { seed: randomSeed() });
  return true;
}

async function confirmSignOut(): Promise<void> {
  hideSignOutPrompt();
  try {
    await signOut();
  } catch {
    return;
  }
  bindPauseState(resetPause());
  stopRunChrome();
  game = undefined;
  entry = undefined;
  gameEnded = false;
  savedGame = undefined;
  renderAccountChip();
  drawGate();
}

