  const detail = (event as CustomEvent<{ game?: string; variation?: string }>).detail;
  launchById(detail?.game, detail?.variation);
});
window.addEventListener("gamepigeon:auth-success", () => {
  clearSignInPending();
  void loadAuthSession().then((user) => {
    if (user) enterArcade(user);
  });
});
window.addEventListener("gamepigeon:auth-error", (event) => {
  clearSignInPending();
  const detail = (event as CustomEvent<unknown>).detail;
  const message = typeof detail === "string" ? detail : "Could not sign in. Try again.";
  setSignInStatus("error", message);
});
window.addEventListener("gamepigeon:sync-error", (event) => {
  const detail = (event as CustomEvent<unknown>).detail;
  setSyncError(typeof detail === "string" ? detail : "Sync paused");
});
