function bootFromQuery(): boolean {
  const params = new URLSearchParams(window.location.search);
  return launchById(params.get("game"), params.get("variation"));
}

function enterArcade(user?: AuthUser): void {
  if (user) {
    const saved = loadSavedGame();
    savedGame = saved?.ownerId === user.id ? saved : undefined;
    unlockTui(user);
  } else {
    const saved = loadSavedGame();
    savedGame = saved?.ownerId === "" ? saved : undefined;
    cursor = -1;
    screen = "menu";
    drawMenu();
  }
  if (bootFromQuery()) return;
  if (settings.resumeLastGame && savedGame) resumeSaved();
}

