{
  const pill = document.querySelector<HTMLButtonElement>("#pill");
  let pillDrag = false;
  let pillOrigin = { x: 0, y: 0 };
  pill?.addEventListener("pointerdown", (event) => {
    pillDrag = false;
    pillOrigin = { x: event.clientX, y: event.clientY };
  });
  pill?.addEventListener("pointermove", (event) => {
    if (event.buttons === 0 || pillDrag) return;
    if (Math.hypot(event.clientX - pillOrigin.x, event.clientY - pillOrigin.y) < 5) return;
    pillDrag = true;
    void windowHandle.startDragging();
  });
  pill?.addEventListener("click", (event) => {
    if (pillDrag) { event.preventDefault(); return; }
    void restoreFromPill();
  });
}

